#!/usr/bin/env bash
set -euo pipefail

plugin="${1:-}"
case "${plugin}" in
  spacewave-core|spacewave-web|spacewave-app|spacewave-notes|spacewave-v86|spacewave-cli-plugin|web)
    ;;
  "")
    echo "usage: $0 <browser-plugin-id>" >&2
    exit 64
    ;;
  *)
    echo "unknown browser plugin release manifest: ${plugin}" >&2
    exit 64
    ;;
esac

target="plugin-release-browser-${plugin}"
backup="$(mktemp)"
cp bldr.star "${backup}"
restore_bldr_star() {
  cp "${backup}" bldr.star
  rm -f "${backup}"
}
trap restore_bldr_star EXIT

cat >> bldr.star <<EOF

# Generated by scripts/release/build-browser-plugin.sh during CI.
build("${target}",
    manifests=["${plugin}"],
    targets=["browser"],
)
EOF

print_diagnostics() {
  local phase="$1"
  echo "::group::${phase} diagnostics (${plugin})"
  echo "disk:"
  df -h
  echo "memory:"
  if command -v free >/dev/null 2>&1; then
    free -h
  elif command -v vm_stat >/dev/null 2>&1; then
    vm_stat
  else
    echo "no free(1) or vm_stat(1) available"
  fi
  echo "::endgroup::"
}

start_seconds="$(date +%s)"
print_diagnostics before
rc=0
bun run bldr -- --build-type=release --watch=false build -b "${target}" || rc="$?"
end_seconds="$(date +%s)"
echo "browser plugin build elapsed_seconds=$((end_seconds - start_seconds)) plugin=${plugin} target=${target} exit_code=${rc}"
print_diagnostics after
exit "${rc}"
